package com.wedo.backend.task.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import com.wedo.backend.activity.entity.*; import com.wedo.backend.activity.service.*; import com.wedo.backend.common.error.*; import com.wedo.backend.group.repository.GroupMembershipRepository; import com.wedo.backend.task.repository.*; import com.wedo.backend.task.entity.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class TaskServiceTest { @Test void claimRequiresCanonicalActiveGroupMembership(){M8ActivityAccessService access=mock(M8ActivityAccessService.class);GroupMembershipRepository members=mock(GroupMembershipRepository.class);TaskRepository tasks=mock(TaskRepository.class);TaskAssigneeRepository assignees=mock(TaskAssigneeRepository.class);UUID taskId=UUID.randomUUID(),actor=UUID.randomUUID(),groupId=UUID.randomUUID();TaskEntity task=new TaskEntity(taskId,UUID.randomUUID(),UUID.randomUUID(),"T",null,null,Instant.EPOCH);when(tasks.findByIdForUpdate(taskId)).thenReturn(Optional.of(task));when(access.requireMutable(task.getActivityId(),actor)).thenReturn(new M8ActivityAccess(activity(task.getActivityId(),groupId),null));when(assignees.countByTaskId(taskId)).thenReturn(0L);when(members.findFirstByGroupIdAndUserIdAndStatus(eq(groupId),eq(actor),any())).thenReturn(Optional.empty());TaskService service=new TaskService(access,members,tasks,assignees,mock(TaskStatusHistoryRepository.class),Clock.systemUTC());BusinessException ex=assertThrows(BusinessException.class,()->service.claim(taskId,actor));assertEquals(ErrorCode.GROUP_MEMBER_NOT_FOUND,ex.errorCode());verify(members).findFirstByGroupIdAndUserIdAndStatus(eq(groupId),eq(actor),any());} @Test void createRejectsAssigneeWithoutActiveGroupMembership(){M8ActivityAccessService access=mock(M8ActivityAccessService.class);GroupMembershipRepository members=mock(GroupMembershipRepository.class);TaskRepository tasks=mock(TaskRepository.class);UUID activityId=UUID.randomUUID(),actor=UUID.randomUUID(),groupId=UUID.randomUUID(),assignee=UUID.randomUUID();when(access.requireMutable(activityId,actor)).thenReturn(new M8ActivityAccess(activity(activityId,groupId),null));when(tasks.save(any())).thenAnswer(i->i.getArgument(0));when(members.findFirstByGroupIdAndUserIdAndStatus(groupId,assignee,com.wedo.backend.group.entity.GroupMembershipStatus.ACTIVE)).thenReturn(Optional.empty());TaskService service=new TaskService(access,members,tasks,mock(TaskAssigneeRepository.class),mock(TaskStatusHistoryRepository.class),Clock.systemUTC());BusinessException ex=assertThrows(BusinessException.class,()->service.create(activityId,actor,new com.wedo.backend.task.dto.CreateTaskRequest("Task",null,List.of(assignee),null)));assertEquals(ErrorCode.GROUP_MEMBER_NOT_FOUND,ex.errorCode());} private ActivityEntity activity(UUID activityId,UUID groupId){return new ActivityEntity(activityId,groupId,UUID.randomUUID(),"A",null,ActivityStatus.CONFIRMED,null,null,null,null,null,Instant.EPOCH,Instant.EPOCH);}}
